import path from "node:path"
import { createRequire } from "node:module"
import {
    mkdirSync, copyFileSync, readFileSync, writeFileSync,
} from "node:fs"

import type { Job, EntryCode } from "./job.ts"

import { licenseFile, readManifest } from "./manifest.ts"

const tool = "packages/lint/scripts/vendor/vendor.ts"

function pluginName(job: Job): string {
    return job.spec.prefix === "" ? "eslint" : job.spec.prefix
}

function header(job: Job): string {
    return `// Generated by ${tool} from ${job.spec.pkg}@${job.manifest.version ?? "?"}. Do not edit.`
}

// Rewriting an unchanged file would break oxlint runs that load it at that moment.
function writeIfChanged(file: string, content: string): void {
    const current = readFileSync(file, { encoding: "utf8", flag: "a+" })
    if (current !== content) {
        writeFileSync(file, content)
    }
}

// Support code shared by patched vendored rules: vendor/_compat/jsx-entities.js
export function writeCompat(lintDir: string): void {
    const estree = path.dirname(createRequire(import.meta.url).resolve("@typescript-eslint/typescript-estree/package.json"))
    const table = readFileSync(path.join(estree, "dist/jsx/xhtml-entities.js"), "utf8")
    const body = table.slice(table.indexOf("exports.xhtmlEntities = {") + "exports.xhtmlEntities = ".length)
    mkdirSync(path.join(lintDir, "vendor/_compat"), { recursive: true })
    writeIfChanged(path.join(lintDir, "vendor/_compat/jsx-entities.js"), [
        `// Generated by ${tool}. Do not edit.`,
        "//",
        "// oxc's ESTree keeps HTML entities undecoded in JSX attribute strings and JSXText `value`",
        "// (`<a b='&quot;'>` → value `&quot;`); typescript-estree, which ESLint used, decodes them (`\"`).",
        "// jsxStringValue() recomputes the decoded value from `raw`, exactly like typescript-estree's",
        `// unescapeStringLiteralText (@typescript-eslint/typescript-estree@${readManifest(estree).version ?? "?"}, MIT).`,
        `const xhtmlEntities = ${body.trim().replace(/;$/u, "")}`,
        "",
        "export function decodeJsxEntities(text) {",
        String.raw`    return text.replaceAll(/&(?:#\d+|#x[\da-fA-F]+|[0-9a-zA-Z]+);/g, (entity) => {`,
        "        const item = entity.slice(1, -1)",
        "        if (item[0] === \"#\") {",
        "            const codePoint = item[1] === \"x\" ? parseInt(item.slice(2), 16) : parseInt(item.slice(1), 10)",
        "",
        "            return codePoint > 0x10ffff ? entity : String.fromCodePoint(codePoint)",
        "        }",
        "",
        "        return xhtmlEntities[item] || entity",
        "    })",
        "}",
        "",
        "// The value typescript-estree gives a JSX attribute string Literal or a JSXText node.",
        "export function jsxStringValue(node) {",
        "    return decodeJsxEntities(node.type === \"JSXText\" ? node.raw : node.raw.slice(1, -1))",
        "}",
        "",
    ].join("\n"))
}

export function writeEntry(job: Job, code: EntryCode): void {
    writeFileSync(path.join(job.target, "index.js"), [
        header(job),
        "// Rules are wrapped by deferReports() so oxlint applies fixes in ESLint's order (see _compat/report-order.js).",
        `import { deferReports } from "../_compat/report-order.js"`,
        ...code.imports,
        "",
        "export default {",
        `    meta:  { name: "${pluginName(job)}" },`,
        "    rules: deferReports({",
        ...code.entries,
        "    }),",
        "}",
        "",
    ].join("\n"))
    writeFileSync(path.join(job.target, "index.d.ts"), [
        header(job),
        "declare const plugin: {",
        "    meta:  { name: string }",
        "    rules: Record<string, unknown>",
        "}",
        "export default plugin",
        "",
    ].join("\n"))
}

export function copyLicense(job: Job): void {
    const license = licenseFile(job.upstream.packageDir)
    if (license !== undefined) {
        copyFileSync(license, path.join(job.target, "LICENSE"))
    }
}

function layoutSentence(job: Job): string {
    const { layout } = job.spec
    if (layout.kind === "rule-files") {
        return "Only the rules enabled in our presets are included; they run inside oxlint as a JS plugin."
    }
    if (layout.kind === "packages") {
        const packages = job.family.map(({ manifest, name }) => `\`${name}@${manifest.version ?? "?"}\``).join(", ")

        return `The upstream plugin is spread over packages of one family; the files it reaches are copied to one folder per package (${packages}; each keeps its LICENSE), with the imports between them rewritten to relative paths. index.js exposes only the rules enabled in our presets. They run inside oxlint as a JS plugin.`
    }

    return "The upstream plugin is a single bundle, copied whole; index.js exposes only the rules enabled in our presets. They run inside oxlint as a JS plugin."
}

// Upstream ranges of the external dependencies (from every copied package of a family).
function dependencyRanges(job: Job): Record<string, string> {
    const own = job.manifest.dependencies ?? {}
    const ranges: Record<string, string> = { ...own }
    for (const { manifest } of job.family) {
        Object.assign(ranges, manifest.dependencies, own)
    }

    return ranges
}

export function writeReadme(job: Job, external: Set<string>): void {
    const {
        manifest, spec, target, upstream,
    } = job
    const ranges = dependencyRanges(job)
    const dependencies = [...external].toSorted().map((name) => `\`${name}\` (upstream range \`${ranges[name] ?? "?"}\`)`)
        .join(", ")
    const patches = Object.entries(typeof spec.patches === "function" ? spec.patches(upstream) : spec.patches ?? {})
    const patchLines = [...new Set(patches.flatMap(([file, list]) => list.map((patch) => `- \`${file}\`: ${patch[2]}`)))].toSorted()
    writeFileSync(path.join(target, "README.md"), [
        `# ${pluginName(job)} (vendored)`,
        "",
        `Copied from \`${spec.pkg}@${manifest.version ?? "?"}\` (${manifest.license ?? "see LICENSE"}) by \`${tool}\`. Do not edit these files by hand: change the spec (\`scripts/vendor/specs/${spec.dir}.ts\`) or the tool, and run \`bun run vendor ${spec.dir}\` in packages/lint.`,
        layoutSentence(job),
        "",
        `Rules (${upstream.rules.length}): ${upstream.rules.map((name) => `\`${name}\``).join(", ")}.`,
        "",
        `External runtime dependencies: ${dependencies === "" ? "none" : dependencies}.`,
        "",
        "## Local patches",
        "",
        ...patchLines.length > 0 ? patchLines : ["None — files are byte-identical to upstream."],
        "",
    ].join("\n"))
}
